import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Glosario","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/glossary.md","filePath":"es/guide/glossary.md"}'),r={name:"es/guide/glossary.md"};function d(n,a,s,l,c,p){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="glossary" tabindex="-1">Glosario <a class="header-anchor" href="#glossary" aria-label="Enlace permanente a &quot;Glosario&quot;">​</a></h1><p><strong>Estado:</strong> Vocabulario del diseño · Cada mecánica conserva su estado indicado.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Skill, Technique, Familiarity y Mastery describen formas distintas de progresar.</li><li>Conocer una opción, prepararla y utilizarla con éxito son pasos separados.</li><li>Usa estas definiciones al leer; consulta las especificaciones enlazadas para ver las reglas detalladas.</li></ul><h2 id="terms-at-a-glance" tabindex="-1">Términos de un vistazo <a class="header-anchor" href="#terms-at-a-glance" aria-label="Enlace permanente a &quot;Términos de un vistazo&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Término</th><th>Significado</th></tr></thead><tbody><tr><td>Skill</td><td>Habilidad: capacidad del personaje en una actividad amplia; no es todo el catálogo de opciones aprendidas.</td></tr><tr><td>Technique</td><td>Técnica: opción o método aprendido; tener suficiente habilidad no enseña automáticamente todas las técnicas.</td></tr><tr><td>Familiarity</td><td>Fluidez práctica con una acción o patrón concreto; distinta de aprenderlo y de la habilidad general.</td></tr><tr><td>Mastery</td><td>Dominio: experiencia profunda o especialización; no equivale a una cifra de habilidad ni al estado de Familiarity llamado Mastered.</td></tr><tr><td>Special Attack (SA)</td><td>Ataque especial: acción marcial aprendida con una utilidad, un compromiso y un coste propios.</td></tr><tr><td>Legacy Combat</td><td>Combate de cadencia automática, conservado como alternativa compatible con el diseño.</td></tr><tr><td>Modern Combat</td><td>El jugador elige cuándo iniciar una acción disponible; elegir el momento no garantiza el éxito.</td></tr><tr><td>Flow</td><td>Ritmo de combate sostenible condicionado por las acciones, el esfuerzo y la recuperación.</td></tr><tr><td>Core Pattern</td><td>Estructura base del hechizo aprendida; las variantes pueden modificarla sin borrar su identidad.</td></tr><tr><td>Active Memory</td><td>Memoria activa: selección de patrones aprendidos preparados para acceder de inmediato al lanzamiento normal, no para lanzar instantáneamente.</td></tr><tr><td>Concentration</td><td>Concentración: estabilidad bajo presión al lanzar o sostener un trabajo mental adecuado; no añade automáticamente otro coste al límite de habilidades.</td></tr><tr><td>Local Trauma</td><td>Trauma local: daño estructural en una región corporal, distinto del daño a la salud global.</td></tr><tr><td>Global Hits</td><td>Salud global, que coexiste con el estado local de las regiones corporales.</td></tr><tr><td>Masterwork</td><td>Obra maestra: logro artesanal excepcional dentro de la propuesta de calidad; no es automáticamente un objeto mágico.</td></tr><tr><td>Latent Property</td><td>Propiedad latente: posible potencial oculto revelado mediante uso o descubrimiento adecuados; no está garantizado en todo buen objeto.</td></tr><tr><td>Profession Path</td><td>Especialización dentro de una profesión, expresada mediante conocimientos y técnicas, sin exigir una habilidad independiente.</td></tr><tr><td>Prepared Repertoire</td><td>Repertorio preparado: opciones marciales elegidas para tenerlas a mano; separado de Active Memory mágica y sin exigir invertir en INT.</td></tr></tbody></table><h2 id="what-s-new-in-syrolands" tabindex="-1">Qué aporta Syrolands <a class="header-anchor" href="#what-s-new-in-syrolands" aria-label="Enlace permanente a &quot;Qué aporta Syrolands&quot;">​</a></h2><p>Estos términos conectan la capacidad del personaje, las decisiones del jugador y el conocimiento aprendido entre sistemas. Algunos nombres son conocidos por UO, pero esta guía utiliza las definiciones de Syrolands; Mastery no equivale automáticamente al sistema posterior Skill Masteries de UO.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Aprendes una Technique, mejoras su Familiarity mediante la práctica y la eliges para tu Prepared Repertoire. Tu Skill sigue importando al intentar usarla; tenerla preparada no garantiza un impacto.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/introduction.html">Introducción</a> · <a href="/Syrolands-Public/es/guide/characters/techniques.html">Técnicas</a> · <a href="/Syrolands-Public/es/guide/characters/familiarity.html">Familiarity</a> · <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria de hechizos</a></p><h2 id="full-design-specification" tabindex="-1">Especificación completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/">Especificaciones de diseño: todos los sistemas y definiciones detalladas</a></p>',14)])])}const h=e(r,[["render",d]]);export{m as __pageData,h as default};
